// The news, painted: once a day, the headlines from a news feed become one
// painting, an allegory of the day rather than a picture of anyone in it,
// with a museum placard saying what it is after. Needs an OpenAI API key.
import { apiKey, askJson, paint, pictureFor, sizeFor, dayKey, MONTHS } from './ai'

const STYLES: Record<string, string> = {
  oil: 'an allegorical oil painting in the manner of the old masters, rich chiaroscuro',
  woodcut: 'a bold woodcut print in three inks',
  watercolor: 'a loose, luminous watercolor',
  editorial: 'a mid-century editorial illustration with flat shapes and grain',
  surreal: 'a surreal dreamscape in the manner of the 1930s surrealists',
  tapestry: 'a richly patterned medieval tapestry',
  fresco: 'a fresco on a sunlit wall, a little faded',
}

const STYLE_NAMES: Record<string, string> = {
  oil: 'Old-master allegory',
  woodcut: 'Woodcut',
  watercolor: 'Watercolor',
  editorial: 'Mid-century illustration',
  surreal: 'Surrealist dreamscape',
  tapestry: 'Tapestry',
  fresco: 'Fresco',
}

const SYSTEM = `You are the curator of a small museum that commissions one painting a day about the day's world news.
From the headlines given, choose the three to four that matter most and imagine one painting that captures the
mood of the day as an allegory: symbolic figures, places, weather and objects. Never depict a real, identifiable
person, never include text, letters, flags with writing or logos, and nothing gory or cruel: grief and conflict
are shown through symbols and light. Answer JSON only:
{"title": "a poetic title, at most 6 words", "prompt": "a detailed prompt for the painter, 60 to 100 words",
"caption": "one sentence for the placard explaining the allegory", "headlines": ["the 3 or 4 headlines you used, shortened to 8 words each"]}`

// Titles and summaries out of an RSS or Atom feed, without an XML parser.
function headlines(feed: string) {
  const items = []
  const blocks = feed.split(/<item[\s>]|<entry[\s>]/).slice(1)
  for (const block of blocks.slice(0, 14)) {
    const title = pick(block, 'title')
    const summary = pick(block, 'description') || pick(block, 'summary')
    if (title) items.push(summary ? `${title}: ${summary.slice(0, 160)}` : title)
  }
  return items
}

function pick(block: string, tag: string) {
  const match = block.match(new RegExp(`<${tag}[^>]*>([\\s\\S]*?)</${tag}>`))
  if (!match) return ''
  return match[1]
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/<[^>]+>/g, '')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
    .trim()
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const now = new Date()
  const today = dayKey(now)
  return pictureFor(app, 'painting', today, 'ai-scenes/news-painted', (path) => {
    const key = apiKey()
    const feed = frameos.fetchText(String(app.config.feedUrl || 'https://feeds.bbci.co.uk/news/world/rss.xml'))
    const news = headlines(feed)
    if (!news.length) throw new Error('No headlines in the news feed')
    const dayNumber = Math.floor(now.getTime() / 86400000)
    const keys = Object.keys(STYLES)
    const styleKey = STYLES[String(app.config.style)] ? String(app.config.style) : keys[dayNumber % keys.length]
    const style = STYLES[styleKey]
    const plan = askJson(key, String(app.config.textModel || 'gpt-6.1-terra'), SYSTEM, `Today is ${now.getDate()} ${MONTHS[now.getMonth()]} ${now.getFullYear()}.\nHeadlines:\n- ${news.join('\n- ')}`)
    const width = context.targetWidth || context.imageWidth || app.frame.width
    const height = context.targetHeight || context.imageHeight || app.frame.height
    const model = String(app.config.imageModel || 'gpt-image-2')
    paint(key, model, `${plan.prompt}\n\nPaint it as ${style}. No text, letters or logos anywhere.`, sizeFor(model, width, height, app.frame.embedded), path, app.frame.embedded)
    return {
      title: String(plan.title || 'Untitled'),
      caption: String(plan.caption || ''),
      headlines: Array.isArray(plan.headlines) ? plan.headlines.slice(0, 4).map(String) : [],
      style: STYLE_NAMES[styleKey],
      date: `${now.getDate()} ${MONTHS[now.getMonth()]} ${now.getFullYear()}`,
    }
  })
}

