// The museum placard beside the day's painting: its title, what it is
// painted as and when, the allegory in a sentence, and the headlines it is
// after. Drawn over the painting, in its lower corner.
import { readRecord } from './record'

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const record = readRecord(app.state.painting)
  const text = record && record.text
  const portrait = H > W
  const u = Math.min(W, H) / 100
  const pad = Math.round(u * 4)
  const cardW = portrait ? W - pad * 2 : Math.round(Math.min(W * 0.42, u * 120))
  const title = Math.round(u * 5)
  const body = Math.round(u * 2.9)
  const small = Math.round(u * 2.4)

  // A round panel shows only the circle inside its square: the placard goes
  // centred in the arc at the bottom, as wide as the circle is at its foot,
  // with the title, the date and the allegory (the headlines want a wider screen).
  if (context.round === true) {
    const d = Math.min(W, H)
    const foot = d * 0.37
    const width = Math.round(2 * Math.sqrt((d / 2) ** 2 - foot ** 2) - 24)
    const roundBody = Math.max(14, Math.round(d * 0.032))
    const roundSmall = Math.max(13, Math.round(d * 0.028))
    return (
      <div className={`flex flex-col w-full h-full items-center justify-end pb-[${Math.round(H / 2 - foot)}px]`}>
        <div className={`flex flex-col items-center text-center w-[${width}px] bg-[#fbf8f2] rounded-[${Math.round(d * 0.02)}px] px-[${Math.round(d * 0.035)}px] py-[${Math.round(d * 0.028)}px]`}>
          <div className={`font-[Cormorant_Garamond] font-bold text-[${Math.round(d * 0.055)}px] leading-tight text-[#1f1b16] line-clamp-2`}>
            {text ? text.title : "Today's painting is on its way"}
          </div>
          {text ? (
            <div className={`font-[PT_Sans] text-[${roundSmall}px] text-[#6d655b] mt-[${Math.round(d * 0.008)}px]`}>{`${text.style} · ${text.date}`}</div>
          ) : null}
          {text && !text.caption ? null : (
            <div className={`font-[PT_Sans] text-[${roundBody}px] leading-snug text-[#2c2620] mt-[${Math.round(d * 0.014)}px] line-clamp-3`}>
              {text ? text.caption : record && record.error ? record.error : 'It is painted once a day from the news. Add an OpenAI API key in Settings.'}
            </div>
          )}
        </div>
      </div>
    )
  }

  if (!text) {
    return (
      <div className={`flex w-full h-full items-end p-[${pad}px]`}>
        <div className={`flex flex-col bg-[#fbf8f2] rounded-[${Math.round(u)}px] p-[${Math.round(u * 3)}px] w-[${cardW}px]`}>
          <div className={`font-[Cormorant_Garamond] font-bold text-[${title}px] text-[#1f1b16]`}>Today's painting is on its way</div>
          <div className={`font-[PT_Sans] text-[${body}px] text-[#6d655b] mt-[${Math.round(u)}px]`}>
            {record && record.error ? record.error : 'It is painted once a day from the news. Add an OpenAI API key in Settings.'}
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className={`flex w-full h-full items-end p-[${pad}px]`}>
      <div className={`flex flex-col bg-[#fbf8f2] rounded-[${Math.round(u * 0.8)}px] px-[${Math.round(u * 3)}px] py-[${Math.round(u * 2.4)}px] w-[${cardW}px]`}>
        <div className={`font-[Cormorant_Garamond] font-bold text-[${title}px] leading-tight text-[#1f1b16]`}>{text.title}</div>
        <div className={`font-[PT_Sans] text-[${small}px] text-[#6d655b] mt-[${Math.round(u * 0.6)}px]`}>
          {`${text.style} · ${text.date}`}
        </div>
        {text.caption ? (
          <div className={`font-[PT_Sans] text-[${body}px] leading-snug text-[#2c2620] mt-[${Math.round(u * 1.4)}px] line-clamp-3`}>{text.caption}</div>
        ) : null}
        {text.headlines && text.headlines.length ? (
          <div className={`flex flex-col border-t border-[#d9d0c2] mt-[${Math.round(u * 1.6)}px] pt-[${Math.round(u * 1.2)}px]`}>
            <div className={`font-[PT_Sans] uppercase text-[${small}px] text-[#9a8f80]`}>After the news</div>
            {text.headlines.map((h: string) => (
              <div className={`font-[PT_Sans] text-[${small}px] text-[#4a423a] truncate`}>{`· ${h}`}</div>
            ))}
          </div>
        ) : null}
      </div>
    </div>
  )
}

